const char* get_cat_help(uint32_t cat) {
    if (cat == ERR::CAT::UNKNOWN) {
        return "";
    }
    if (cat == ERR::CAT::HUB_NOT_FOUND) {
        return
            "Check that the IniSystem created the hub entity in on_start(), that spawn created the hub values "
                "for the entity, that the owner ID is the right one and that the value_id carries no typo";
    }
    if (cat == ERR::CAT::HUB_GLOBAL_MISSING) {
        return
            "Check that the source module's IniSystem created the GLOBAL hub value, that the source module is "
                "loaded and that the value_id carries no typo";
    }
    if (cat == ERR::CAT::COMPONENT_MISSING) {
        return
            "Check that the entity was spawned with its required components and that no other system removed "
                "the component";
    }
    if (cat == ERR::CAT::MANAGER_ABSENT) {
        return
            "Check that some system creates the manager entity and gives it its tag, and that the schedule "
                "places that creation before this system. An empty view means no entity carries the tag at all, "
                "so there is nothing to look inside";
    }
    if (cat == ERR::CAT::INVALID_ENTITY) {
        return
            "Check that the entity was not destroyed, that the stored entity ID is the right one and that no "
                "dangling reference survived";
    }
    if (cat == ERR::CAT::SCHEDULE_ORDER) {
        return
            "Check that the producer system is scheduled earlier and that the module definition carries the "
                ".run_after() constraint";
    }
    if (cat == ERR::CAT::CONFIG_MISSING) {
        return
            "Check that the variable is set in the unit's .env, that the .env is loaded before the plugin "
                "starts, that the variable name carries no typo and that the value is not empty";
    }
    if (cat == ERR::CAT::RESOURCE_UNAVAIL) {
        return
            "Check that the resource exists, is reachable AND not empty, because a file of zero length passes "
                "every existence test and still yields nothing. Then check the permissions on path or port, that "
                "the capacity of arena, buffer or descriptors is not exhausted, that the previous holder released "
                "it and that the read completed, since a short read leaves the resource present and unusable";
    }
    if (cat == ERR::CAT::ACCESS_DENIED) {
        return
            "Check that the caller identity was resolved before the check and that the required clearance or "
                "permission is recorded for that identity. The decision belongs in the error stream, not as a "
                "warning";
    }
    if (cat == ERR::CAT::WORK_PRECLUDED) {
        return
            "State noted. Nothing is missing, unreachable or unset and the work does not apply here";
    }
    if (cat == ERR::CAT::INPUT_TOO_LARGE) {
        return
            "Check the caller's payload against the documented cap and the cap itself against its intended "
                "value. Nothing was stored or forwarded because the whole input was rejected";
    }
    if (cat == ERR::CAT::HOST_OP_FAILED) {
        return
            "Check that the named path, handle or program is the intended one, then permissions and free "
                "space, then the OS error text in detail. That text names the cause while the category only names "
                "the class. On a REMOTE host the same checks apply to the far side, the reply carries the error "
                "text and local permissions and disk are the wrong trail";
    }
    if (cat == ERR::CAT::INPUT_TRUNCATED) {
        return
            "Check the declared length against what actually arrived and whether the sender split the "
                "message. Nothing was decoded because a short frame yields no partial result";
    }
    if (cat == ERR::CAT::REFERENCE_UNRESOLVED) {
        return
            "Check the PRODUCER of the reference, not this caller. Ask whether the target was ever created, "
                "whether a later step removed it and whether the reference stems from an older structure version";
    }
    if (cat == ERR::CAT::INPUT_REJECTED) {
        return
            "Check what the caller sent against what the contract allows and whether the rejection is the "
                "intended answer. Nothing was processed and this is not an engine fault";
    }
    if (cat == ERR::CAT::CAPACITY_REACHED) {
        return
            "Check the capacity itself first, because a container that is always full is sized wrong, not "
                "busy. Then check the producer rate against the drain rate, and what was refused and whether it "
                "can be retried";
    }
    if (cat == ERR::CAT::UNKNOWN_ID) {
        return
            "Check the spelling of the identifier against the registry that owns it, whether the producer "
                "registered it before this call and whether the registry itself is the one you expect";
    }
    if (cat == ERR::CAT::BUFFER_TOO_SMALL) {
        return
            "Check the buffer size at the CALLER, which owns the buffer rather than this function, against "
                "the maximum this operation can produce. Nothing was written because a short buffer yields no "
                "partial result";
    }
    if (cat == ERR::CAT::VERSION_MISMATCH) {
        return
            "Check expected against received, and both belong in the line. Then check which side is older and "
                "whether the two were built from the same tree";
    }
    if (cat == ERR::CAT::VALUE_OUT_OF_RANGE) {
        return
            "Check the value against the range that rejected it and decide which side is wrong, the value or "
                "the range. Nothing was applied and the operation ends here";
    }
    if (cat == ERR::CAT::VALUE_NEGATIVE) {
        return
            "Check the producer of the value, because a negative here is not correctable at this end, and "
                "whether a subtraction underflowed. Nothing was applied and the operation ends here";
    }
    if (cat == ERR::CAT::VALUE_INVALID) {
        return
            "Check what the value means in the contract that rejected it and the producer that wrote it. "
                "Nothing was applied and the operation ends here";
    }

    return
        "The value passed is not a category in core/ase-log/data/log_categories.json. Check the constant "
            "at the call site: a category is ERR::CAT::<NAME> or WRN::CAT::<NAME>, and its value is the hash "
            "of that NAME - a hand-written number cannot be one.";
}

