const char* get_cat_tail(uint32_t cat) {
    if (cat == ERR::CAT::UNKNOWN) {
        return "";
    }
    if (cat == ERR::CAT::HUB_NOT_FOUND) {
        return
            "\n\x1b[38;2;108;108;108m    "
            "chk IniSystem crtd hub enty in on_start(), spawn crtd hub values for enty, owner ID is right one "
                "and val_id carries no typo"
            "\x1b[0m\n";
    }
    if (cat == ERR::CAT::HUB_GLOBAL_MISSING) {
        return
            "\n\x1b[38;2;108;108;108m    "
            "chk src mod's IniSystem crtd glob hub val, src mod is lded and val_id carries no typo"
            "\x1b[0m\n";
    }
    if (cat == ERR::CAT::COMPONENT_MISSING) {
        return
            "\n\x1b[38;2;108;108;108m    "
            "chk enty was spawned with reqd components and no other sys rmvd comp"
            "\x1b[0m\n";
    }
    if (cat == ERR::CAT::MANAGER_ABSENT) {
        return
            "\n\x1b[38;2;108;108;108m    "
            "chk some sys creates mgr enty and gives it tag, and schd places creation bfr sys. empty view mns "
                "no enty carries tag at all, so there is nothing to look insd"
            "\x1b[0m\n";
    }
    if (cat == ERR::CAT::INVALID_ENTITY) {
        return
            "\n\x1b[38;2;108;108;108m    "
            "chk enty was not dstd, strd enty ID is right one and no dang ref survived"
            "\x1b[0m\n";
    }
    if (cat == ERR::CAT::SCHEDULE_ORDER) {
        return
            "\n\x1b[38;2;108;108;108m    "
            "chk prod sys is schd earlier and mod defn carries .run_after() cstr"
            "\x1b[0m\n";
    }
    if (cat == ERR::CAT::CONFIG_MISSING) {
        return
            "\n\x1b[38;2;108;108;108m    "
            "chk var is set in unit's .env, .env is lded bfr plgn starts, var name carries no typo and val is "
                "not empty"
            "\x1b[0m\n";
    }
    if (cat == ERR::CAT::RESOURCE_UNAVAIL) {
        return
            "\n\x1b[38;2;108;108;108m    "
            "chk rsrc exists, is reachable AND not empty, because file of zero len passes every exst test and "
                "still yields nothing. Then chk permissions on path or port, cap of arena, buf or descriptors is "
                "not exht, prev hldr rlsd it and read cmpl, since short read leaves rsrc pres and unusable"
            "\x1b[0m\n";
    }
    if (cat == ERR::CAT::ACCESS_DENIED) {
        return
            "\n\x1b[38;2;108;108;108m    "
            "chk caller idnt was resolved bfr chk and reqd clrn or perm is recorded for idnt. dcsn belongs in "
                "err strm, not as warn"
            "\x1b[0m\n";
    }
    if (cat == ERR::CAT::WORK_PRECLUDED) {
        return
            "\n\x1b[38;2;108;108;108m    "
            "State noted. Nothing is miss, unrc or unset and work does not apply here"
            "\x1b[0m\n";
    }
    if (cat == ERR::CAT::INPUT_TOO_LARGE) {
        return
            "\n\x1b[38;2;108;108;108m    "
            "chk caller's pyld against documented cap and cap itself against intended val. Nothing was strd "
                "or forwarded because whole inp was rjct"
            "\x1b[0m\n";
    }
    if (cat == ERR::CAT::HOST_OP_FAILED) {
        return
            "\n\x1b[38;2;108;108;108m    "
            "chk named path, hndl or program is intended one, then permissions and free space, then OS err "
                "text in detl. text names cause while cat only names cls. On REMOTE host same checks apply to far "
                "side, reply carries err text and local permissions and disk are wrong trl"
            "\x1b[0m\n";
    }
    if (cat == ERR::CAT::INPUT_TRUNCATED) {
        return
            "\n\x1b[38;2;108;108;108m    "
            "chk declared len against what actually arvd and whether sndr split msg. Nothing was decd because "
                "short frame yields no prtl rslt"
            "\x1b[0m\n";
    }
    if (cat == ERR::CAT::REFERENCE_UNRESOLVED) {
        return
            "\n\x1b[38;2;108;108;108m    "
            "chk prod of ref, not caller. Ask whether tgt was ever crtd, whether later step rmvd it and "
                "whether ref stems from older strc ver"
            "\x1b[0m\n";
    }
    if (cat == ERR::CAT::INPUT_REJECTED) {
        return
            "\n\x1b[38;2;108;108;108m    "
            "chk what caller sent against what cntr allows and whether rjct is intended answer. Nothing was "
                "processed and is not engn fault"
            "\x1b[0m\n";
    }
    if (cat == ERR::CAT::CAPACITY_REACHED) {
        return
            "\n\x1b[38;2;108;108;108m    "
            "chk cap itself fst, because container is always full is sized wrong, not busy. Then chk prod "
                "rate against drn rate, and what was refused and whether it can be retried"
            "\x1b[0m\n";
    }
    if (cat == ERR::CAT::UNKNOWN_ID) {
        return
            "\n\x1b[38;2;108;108;108m    "
            "chk spelling of idnt against reg owns it, whether prod registered it bfr call and whether reg "
                "itself is one you expect"
            "\x1b[0m\n";
    }
    if (cat == ERR::CAT::BUFFER_TOO_SMALL) {
        return
            "\n\x1b[38;2;108;108;108m    "
            "chk buf size at CALLER, which owns buf rather than func, against maxm operation can produce. "
                "Nothing was written because short buf yields no prtl rslt"
            "\x1b[0m\n";
    }
    if (cat == ERR::CAT::VERSION_MISMATCH) {
        return
            "\n\x1b[38;2;108;108;108m    "
            "chk expc against received, and both blng in line. Then chk which side is older and whether two "
                "were blt from same tree"
            "\x1b[0m\n";
    }
    if (cat == ERR::CAT::VALUE_OUT_OF_RANGE) {
        return
            "\n\x1b[38;2;108;108;108m    "
            "chk val against rng rjct it and dcde which side is wrong, val or rng. Nothing was applied and "
                "operation ends here"
            "\x1b[0m\n";
    }
    if (cat == ERR::CAT::VALUE_NEGATIVE) {
        return
            "\n\x1b[38;2;108;108;108m    "
            "chk prod of val, because negv here is not correctable at end, and whether subtraction "
                "underflowed. Nothing was applied and operation ends here"
            "\x1b[0m\n";
    }
    if (cat == ERR::CAT::VALUE_INVALID) {
        return
            "\n\x1b[38;2;108;108;108m    "
            "chk what val mns in cntr rjct it and prod wrote it. Nothing was applied and operation ends here"
            "\x1b[0m\n";
    }

    return
        "\n\x1b[38;2;108;108;108m    "
        "val passed is not cat in core/ase-log/data/log_categories.json. chk constant at call site: cat "
            "is ERR::CAT::<NAME> or WRN::CAT::<NAME>, and val is hash of NAME - hand-written num cant be one."
        "\x1b[0m\n";
}

